n=21
g=[[0]*n for _ in range(n)]
pts={3:[(0,14),(3,17),(5,9),(6,10),(6,13),(8,15),(8,17)],6:[(2,3),(17,3)],1:[(2,7),(17,7)],7:[(2,6)],4:[(3,2)],8:[(13,10),(15,16),(17,13)]}
for color,ps in pts.items():
    for r,c in ps:g[r][c]=color
# draw straight horizontal, vertical, or diagonal connectors for every aligned pair
for color,ps in pts.items():
    for i,(r1,c1) in enumerate(ps):
        for r2,c2 in ps[i+1:]:
            dr,dc=r2-r1,c2-c1
            if dr==0 or dc==0 or abs(dr)==abs(dc):
                steps=max(abs(dr),abs(dc))
                sr=0 if dr==0 else dr//abs(dr)
                sc=0 if dc==0 else dc//abs(dc)
                for k in range(steps+1):
                    r,c=r1+k*sr,c1+k*sc
                    if g[r][c] in (0,color):g[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

